// Rebuild 365 days as one source-evidence matrix, not 365 invented saints.
// Inputs are generated by the existing real Calendar day-resolver census.
// No string-based canonization decisions, physical map pins or art selection.
import assert from "node:assert/strict";
import {readFileSync,writeFileSync,mkdirSync} from "node:fs";
import {resolve,dirname} from "node:path";
import {fileURLToPath} from "node:url";
const root=resolve(fileURLToPath(new URL("../..",import.meta.url)));
const dir=resolve(root,"artifacts/saints-calendar-census");
const read=p=>JSON.parse(readFileSync(resolve(root,p),"utf8"));
const sourceFile=p=>"artifacts/saints-calendar-census/"+p;
const observed=read(sourceFile("saints-calendar-2026-observed-owner-census.json"));
const candidates=read(sourceFile("saints-2026-daily-subject-demand-review.json"));
const archiveJoin=read(sourceFile("saints-v4333-311-component-observed-2026-join.json"));
const identities=read("data/saints/full-calendar-exact-source-key-ledger-20261016.v1.json");
assert.equal(observed.schema,"ao.saints.2026-observed-liturgical-day-census.v1");
assert.equal(candidates.schema,"ao.saints.2026-observed-daily-subject-demand.v1");
assert.equal(archiveJoin.schema,"ao.saints.v4333-art-components-to-observed-2026.v1");
assert.equal(identities.schema,"ao.saints.full-register-exact-source-keys.2026.v1");
assert.equal(identities.summary.exact_source_key_union_including_modern_collectives,608);
assert.equal(observed.days.length,365);
assert.equal(candidates.days.length,365);
assert.equal(archiveJoin.rows.length,252);

const byDate=new Map(archiveJoin.rows.map(r=>[r.observed_date_2026,r]));
const demandByDate=new Map(candidates.days.map(r=>[r.date,r]));
assert.equal(byDate.size,252);assert.equal(demandByDate.size,365);
const historicalSourceIds=new Set(archiveJoin.rows.flatMap(r=>r.source_observances.map(s=>s.historical_source_id)));
const observedSourceIds=new Set();
const missing=new Map();
const allLexical={};
const monthStats=Object.fromEntries(Array.from({length:12},(_,i)=>[
 String(i+1).padStart(2,"0"),
 {resolved_days:0,observed_sanctoral_principals:0,named_commemoration_occurrences:0,
  subject_mentions:0,days_with_subject_mentions:0,observed_source_ids_missing_from_historical_archive:0}
]));
const days=[];
for(const day of observed.days){
 const nominal=day.date.slice(5),d=demandByDate.get(day.date),historical=byDate.get(day.date);
 assert(d&&day.date===d.date,"Daily demand drift "+day.date);
 const principal=day.principal;
 const commemorations=day.commemorations.canonical_rows??[];
 const seenOnDate=new Set();
 const sourceOccurrences=[
   ...(principal.observed_cycle==="sanctorale"?[{
     category:"OBSERVED_SANCTORAL_PRINCIPAL",source_id:principal.source_id,
     title_en:principal.title_en,title_fr:principal.title_fr}]:[]),
   ...commemorations.map(x=>({
     category:"OBSERVED_NAMED_COMMEMORATION",source_id:x.source_id,
     title_en:x.title,title_fr:x.title_fr}))];
 // The Calendar resolver, not textual parsing, establishes source IDs.
 for(const event of sourceOccurrences){
   assert(event.source_id,"Observed Calendar source ID missing on "+day.date);
   assert(!seenOnDate.has(event.source_id),"Duplicate same-day source ID "+event.source_id);
   seenOnDate.add(event.source_id);
   observedSourceIds.add(event.source_id);
   if(!historicalSourceIds.has(event.source_id)){
     const entry=missing.get(event.source_id)??{
       source_id:event.source_id,dates:[],titles:[],evidence_status:"OBSERVED_CALENDAR_SOURCE_ID_NOT_IN_HISTORICAL_ART_ARCHIVE",
       identity_status:"PERSON_GROUP_OR_EVENT_NOT_ADJUDICATED",identity_id:null};
     if(!entry.dates.includes(day.date))entry.dates.push(day.date);
     if(!entry.titles.includes(event.title_en))entry.titles.push(event.title_en);
     missing.set(event.source_id,entry);
   }
 }
 const demandSources=d.candidate_subject_demands;
 for(const event of demandSources){
   assert(event.identity_id===null&&event.physical_artwork_id===null,"Demand inventory incorrectly promotes an identity");
   allLexical[event.title_hint]=(allLexical[event.title_hint]??0)+1;
 }
 assert.equal(d.candidate_count,demandSources.length);
 assert.equal(d.candidate_count,sourceOccurrences.length,
   "Observed named commemoration did not reconcile to one source mention on "+day.date);
 const archived=historical?{
   archived_nominal_components:historical.historical_art_components.map(x=>({
     component_id:x.historical_component_id,archived_subject_key:x.historical_identity_id,
     representation_mode:x.historical_representation_mode,
     current_person_identity_certified:false,approved_artwork_id:null})),
   nominal_observances:historical.source_observances.map(x=>({
     original_source_id:x.historical_source_id,observed_match_kind:x.observed_match_kind})),
   exact_archive_principal_or_commemoration:historical.source_overlap_summary
 }:null;
 const items=demandSources.map((event,i)=>({
   source_id:sourceOccurrences[i]?.source_id??event.source_id,
   source_slot:sourceOccurrences[i]?.category??event.entry_type,
   title_en:event.title_en,title_fr:event.title_fr,
   provisional_title_hint:event.title_hint,
   exact_source_id_in_historical_archive:historicalSourceIds.has(sourceOccurrences[i]?.source_id??event.source_id),
   saint_or_group_person_identity_id:null,identity_review:"NOT_INFERRED_FROM_FEAST_HEADING",
   artwork_approved_id:null
 }));
 const month=day.date.slice(5,7),m=monthStats[month];
 assert(m,"Invalid date month "+day.date);
 m.resolved_days++;
 if(principal.observed_cycle==="sanctorale")m.observed_sanctoral_principals++;
 m.named_commemoration_occurrences+=commemorations.length;
 m.subject_mentions+=items.length;
 if(items.length)m.days_with_subject_mentions++;
 m.observed_source_ids_missing_from_historical_archive+=items.filter(x=>!x.exact_source_id_in_historical_archive).length;
 days.push({
   date:day.date,calendar_observed_source_id:principal.source_id,
   calendar_observed_title_en:principal.title_en,
   calendar_observed_title_fr:principal.title_fr,
   observed_cycle:principal.observed_cycle,calendar_source_rank:principal.raw_rank,
   observed_named_commemoration_ids:commemorations.map(x=>x.source_id),
   candidate_source_subjects:items,
   archived_subjects_on_nominal_date:archived,
   art_status:"NOT_AUDITED_AGAINST_APPROVED_MASTERS",
   identity_certification:"NONE_FROM_SOURCE_JOIN"
 });
}
const exactObserved=[...observedSourceIds].filter(id=>historicalSourceIds.has(id));
assert.equal(days.length,365);
assert.equal(days.filter(x=>x.candidate_source_subjects.length>0).length,222);
assert.equal(days.reduce((n,x)=>n+x.candidate_source_subjects.length,0),282);
assert.equal(observedSourceIds.size,282);
assert.equal(historicalSourceIds.size,314);
assert.equal(exactObserved.length,240);
assert.equal(missing.size,42);
assert.equal(archiveJoin.summary.source_observed_as_principal,142);
assert.equal(archiveJoin.summary.source_exactly_commemorated,99);
assert.equal(archiveJoin.summary.source_no_exact_same_date_match,73);
assert.equal(archiveJoin.summary.unique_historical_ids,307);
assert.equal(Object.values(monthStats).reduce((s,m)=>s+m.resolved_days,0),365);
const gaps=[...missing.values()].sort((a,b)=>a.source_id.localeCompare(b.source_id));
const summary={
 year:2026,days_observed:365,observed_sanctoral_principals:165,
 observed_named_commemoration_occurrences:117,
 days_with_sanctoral_or_named_commemoration_subject:222,
 candidate_observed_source_subject_occurrences:282,
 observed_distinct_source_ids:observedSourceIds.size,
 archived_historical_component_records:archiveJoin.summary.historical_components,
 archived_historical_source_subject_keys:archiveJoin.summary.unique_historical_ids,
 archived_distinct_observance_source_ids:historicalSourceIds.size,
 exact_observed_source_ids_found_in_archive:exactObserved.length,
 observed_source_ids_absent_from_archive:missing.size,
 archived_source_ids_not_in_observed_source_set:historicalSourceIds.size-exactObserved.length,
 archived_observance_occurrences_matching_2026_principal:archiveJoin.summary.source_observed_as_principal,
 archived_observance_occurrences_matching_2026_commemoration:archiveJoin.summary.source_exactly_commemorated,
 archived_observance_occurrences_not_exactly_observed_on_nominal_day:archiveJoin.summary.source_no_exact_same_date_match,
 exact_source_key_ledger_records_including_collectives:identities.records.length,
 archival_identity_overlap_with_modern_and_profiles:identities.summary.keys_in_multiple_owner_families,
 individual_saints_certified_from_lexical_titles:0,artwork_masters_selected:0,new_map_pins:0};
const sourceProvenance={
 observed_calendar:"saints-calendar-2026-observed-owner-census.json · live original AO_RUNTIME_V8.resolveDay for all 365 days",
 source_demands:"saints-2026-daily-subject-demand-review.json · observed titles only",
 archive:"saints-v4333-311-component-observed-2026-join.json · original 311 component IDs",
 cross_owner:"data/saints/full-calendar-exact-source-key-ledger-20261016.v1.json · read-only 608 exact keys",
 build_commit:process.env.GITHUB_SHA??null
};
const matrix={schema:"ao.saints.2026-full-365-calendar-source-coverage-matrix.v1",
 publication:"RESEARCH_ONLY_NOT_A_1962_LITURGICAL_AUTHORITY",
 source_provenance:sourceProvenance,
 counting_rules:[
  "Calendar has 365 observed 2026 civil days; this is not a claim of 365 distinct named saint feasts.",
  "One day may contain no source-identified saint, one main sanctoral source and many named commemorations.",
  "Observed source IDs and archival saint/art subject keys have different namespaces and MUST NOT be equated.",
  "Only exact raw Calendar observance IDs are joined to the frozen historical art archive.",
  "Individual, group, Marian, Angelic, Christological and liturgical-event subjects are separately adjudicated; title hints do not certify identities.",
  "The 608 source keys are not 608 distinct canonized individuals or 608 approved images.",
  "No independent 1962 calendar ruling, Mass Proper, canonization, portrait or geographic pin is published."
 ],summary,monthly:monthStats,lexical_title_hints:allLexical,
 days};
const gapQueue={schema:"ao.saints.2026-observed-source-id-gap-queue.v1",
 status:"SOURCE_OBSERVANCE_RECONCILIATION_NOT_MISSING_SAINT_PROOF",
 source_provenance:sourceProvenance,
 summary:{distinct_observed_ids_not_in_archive:gaps.length,
  warning:"These include event/Marian/group observances. Do not create people from missing source IDs."},
 missing_ids:gaps};
mkdirSync(dir,{recursive:true});
const write=(filename,value)=>writeFileSync(resolve(dir,filename),JSON.stringify(value,null,2)+"\n");
write("saints-2026-full-365-coverage-matrix.json",matrix);
write("saints-2026-observed-42-source-gaps.json",gapQueue);
const report=[
 "# Ad Orientem Saints · 2026 all-365-day source coverage",
 "",
 "Generated from the original 2026 Calendar resolver and frozen Saints source evidence; **not** a corrected calendar or a biography certification.",
 "",
 "| Coverage dimension | Evidence-backed count |",
 "| --- | ---: |",
 ...Object.entries(summary).filter(([k])=>k!=="year").map(([k,v])=>"| "+k.replaceAll("_"," ")+" | "+v+" |"),
 "",
 "## 42 missing raw observed-source references",
 "",
 "The 42 IDs are absent from the *frozen historical artwork-source register*. They are **not** 42 proven missing saints. Classify event, group and person source slots before setting biography requirements.",
 "",
 ...gaps.map(x=>"- \`"+x.source_id+"\` · "+x.dates.join(", ")+" · "+x.titles.join(" / ")),
 "",
 "## Identity and art boundary",
 "",
 "The cross-owner union contains **608 distinct exact source keys**, not a final unique-Saint denominator. The 365-day matrix has no inferred \`saint_id\`, geolocation, approved image or automatically entered Mass.",
 ""
].join("\n");
writeFileSync(resolve(dir,"saints-2026-coverage-report.md"),report);
console.log("PASS all-365-days + 608 exact-key union + 42 observed source-reference exceptions: "+JSON.stringify(summary));